import React, { useEffect, useState } from "react";
import { NavLink } from "react-router-dom";
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  CartesianGrid,
} from "recharts";

function AdminHub() {
  const [sales, setSales] = useState([]);
  const [chartData, setChartData] = useState([]);

  const user = JSON.parse(localStorage.getItem("user"));

  useEffect(() => {
    fetchSales();
  }, []);

  const fetchSales = async () => {
    try {
      const res = await fetch(
        `http://localhost:5000/api/orders/sales/${user._id}`
      );
      const data = await res.json();

      setSales(data);
      processChartData(data);
    } catch (err) {
      console.error(err);
    }
  };

  const processChartData = (data) => {
    const grouped = {};

    data.forEach((sale) => {
      const date = new Date(sale.purchasedAt).toLocaleDateString();

      if (!grouped[date]) {
        grouped[date] = 0;
      }

      grouped[date] += Number(sale.price);
    });

    const formatted = Object.keys(grouped).map((date) => ({
      date,
      revenue: grouped[date],
    }));

    setChartData(formatted);
  };

  const totalRevenue = sales.reduce(
    (acc, sale) => acc + Number(sale.price || 0),
    0
  );

  return (
    <>
      <div className="KO">
      {/* Navigational sidebar */}
        <div className="Mother">

         <div className="Sidebar">
            <h2 className="dashboard-title"><font style={{color: '#eef0bb' }}>A</font><font style={{color: '#fbebc1' }}>d</font><font style={{color: '#bcdef4'}}>m</font><font style={{color: '#e4c8e0'}}>i</font><font style={{color: '#fac7c7'}}>n</font> Hub</h2>
            
            <NavLink id="places" to="/AdminHub" className={({ isActive }) => isActive ? "nav-links active" : "nav-links"}
 >
              Dashboard
            </NavLink>
            <NavLink id="places" to="/DashboardBooks" className={({ isActive }) => isActive ? "nav-links active" : "nav-links"}
            >
              Add Books
            </NavLink>
            <NavLink id="places" to="/DashboardBooksList" className={({ isActive }) => isActive ? "nav-links active" : "nav-links"}
            >
              My Listings
            </NavLink>
            <NavLink id="places" to="/DashboardPurchases" className={({ isActive }) => isActive ? "nav-links active" : "nav-links"}
            >
              Purchases
            </NavLink>
            <NavLink id="places" to="/DashboardPayment" className={({ isActive }) => isActive ? "nav-links active" : "nav-links"}
            >
              Payment
            </NavLink>
            <NavLink id="places" to="/DashboardSales" className={({ isActive }) => isActive ? "nav-links active" : "nav-links"}
            >
              Sales
            </NavLink>
            <NavLink id="home" to="/Home" className="nav-link return-main">
              Return to Main Site
            </NavLink>
            <NavLink
              id="hometo"
              to="/"
              className="nav-link return-main"
              onClick={() => {
                localStorage.removeItem("token");  // ✅ remove token
                localStorage.removeItem("user");   // optional if you stored user separately
              }}
            >
              Log Out
            </NavLink>
            </div>
          </div>
                {/* Overview stats */}
          <div className="Daughter">
          <div className="Vertible">


            {/* Stats */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-10">
          <div className="bg-white p-5 rounded shadow">
            <p>Total Sales</p>
            <h2 className="text-2xl font-bold">{sales.length}</h2>
          </div>

          <div className="bg-white p-5 rounded shadow">
            <p>Total Revenue</p>
            <h2 className="text-2xl font-bold">${totalRevenue.toFixed(2)}</h2>
          </div>

          <div className="bg-white p-5 rounded shadow">
            <p>Avg Order Value</p>
            <h2 className="text-2xl font-bold">
              ${sales.length ? (totalRevenue / sales.length).toFixed(2) : 0}
            </h2>
          </div>
        </div>

        {/* Chart */}
        <div className="bg-white p-6 rounded shadow">
          <h2 className="mb-4 text-xl font-semibold">Revenue Over Time</h2>

          <ResponsiveContainer width="100%" height={300}>
            <LineChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="date" />
              <YAxis />
              <Tooltip />
              <Line type="monotone" dataKey="revenue" />
            </LineChart>
          </ResponsiveContainer>
        </div>
          </div>
          </div>
        </div>
    </>
  );
}

export default AdminHub;
